236: 			PrefixLen: uint32(masklen),
237: 			Rd:        rdAttr,
238: 		})
239: 		if err != nil {
240: 			return nil, err
241: 		}
242: 	} else {
243: 		nlri, err = ptypes.MarshalAny(&bgpapi.IPAddressPrefix{
244: 			Prefix:    p.String(),
245: 			PrefixLen: uint32(masklen),
246: 		})
247: 		if err != nil {
248: 			return nil, err
249: 		}
250: 	}
251: 	var family *bgpapi.Family
252: 	originAttr, err := ptypes.MarshalAny(&bgpapi.OriginAttribute{Origin: 0})
253: 	if err != nil {
254: 		return nil, err
255: 	}
256: 	attrs := []*any.Any{originAttr}
257: 
258: 	if v4 {
259: 		if nodeIpv4 == nil {
260: 			return nil, fmt.Errorf("No ip4 address for node")
261: 		}
262: 		family = &BgpFamilyUnicastIPv4
263: 		if vni != 0 {
264: 			family = &BgpFamilyUnicastIPv4VPN
265: 		}
266: 		var nhAttr *any.Any
267: 
268: 		if config.EnableSRv6 {
269: 			nhAttr, err = ptypes.MarshalAny(&bgpapi.NextHopAttribute{
270: 				NextHop: nodeIpv6.String(),
271: 			})
272: 		} else {
273: 			nhAttr, err = ptypes.MarshalAny(&bgpapi.NextHopAttribute{
274: 				NextHop: nodeIpv4.String(),
275: 			})
276: 		}
277: 		if err != nil {
278: 			return nil, err
279: 		}
280: 		attrs = append(attrs, nhAttr)
281: 	} else {
282: 		if nodeIpv6 == nil {
283: 			return nil, fmt.Errorf("No ip6 address for node")
284: 		}
285: 		family = &BgpFamilyUnicastIPv6
286: 		if vni != 0 {
287: 			family = &BgpFamilyUnicastIPv6VPN
288: 		}
289: 		var nlriAttr *anypb.Any
290: 		var familySafi bgpapi.Family_Safi
291: 		if vni != 0 {
292: 			familySafi = bgpapi.Family_SAFI_MPLS_VPN
293: 		} else {
294: 			familySafi = bgpapi.Family_SAFI_UNICAST
295: 		}
296: 		nlriAttr, err = ptypes.MarshalAny(&bgpapi.MpReachNLRIAttribute{
297: 			NextHops: []string{nodeIpv6.String()},
298: 			Nlris:    []*any.Any{nlri},
299: 			Family: &bgpapi.Family{
300: 				Afi:  bgpapi.Family_AFI_IP6,
301: 				Safi: familySafi,
302: 			},
303: 		})
304: 		if err != nil {
305: 			return nil, err
306: 		}
307: 		attrs = append(attrs, nlriAttr)
308: 	}
309: 
310: 	return &bgpapi.Path{
311: 		Nlri:       nlri,
312: 		IsWithdraw: isWithdrawal,
313: 		Pattrs:     attrs,
314: 		Age:        ptypes.TimestampNow(),
315: 		Family:     family,
316: 	}, nil
317: }
